from sympy import symbols
x = symbols("x")

count = int(input())
for i in range(count):
    k = int(input())
    terms = []
    for j in range(k):
        coef = int(input())
        power = int(input())
        terms.append((coef, power))
    totals = {}
    for coef, power in terms:
        if power in totals:
            totals[power] = totals[power] + coef
        else:
            totals[power] = coef
    print(f"Problem {i + 1}:")
    for power in sorted(totals):
        print(f"  x^{power}: {totals[power]}")
    check = 0
    for coef, power in terms:
        check = check + coef * x**power
    print(f"  sympy: {check}")
